/**
 * Gap Register: each gap recorded in the published graph as one structured, inspectable object.
 * Everything here is derived from the published bundle; nothing is generated by a model and nothing is a finding.
 * Priority is a transparent ordering aid (factors are returned), not a judgement of scientific value.
 * Status and history are user-owned and live outside this module (browser-local today).
 */
import type {DomainBundle,DomainEdge,DomainGap,DomainModel} from "./domainGraph";

export type GapStatus="open"|"investigating"|"resolved"|"deferred";
export const GAP_STATUSES:readonly GapStatus[]=["open","investigating","resolved","deferred"];
export type GapEvidenceRef={edgeId:string;sourceId:string|null;predicate:string;assertion:string;model:DomainModel;design:string;limitations:string;reviewStatus:string};
export type GapRegisterEntry={
 id:string;graphVersion:string;question:string;missing:string;
 subject:{id:string;name:string};object:{id:string;name:string};
 domains:string[];conditions:string[];
 /** Candidate relationships that touch either concept and are not negated. Candidates, unreviewed. */
 touching:GapEvidenceRef[];
 /** Touching candidate relationships recorded as negated (the source reports no or opposite effect). */
 opposing:GapEvidenceRef[];
 evidenceModels:Partial<Record<DomainModel,number>>;
 candidateExperiments:string[];
 uncertainty:{level:"high"|"moderate";reasons:string[]};
 priority:{score:number;factors:{label:string;points:number}[];note:string};
};
const HUMAN=new Set<DomainModel>(["human_in_vivo","human_ex_vivo","human_cell_line"]);
const ref=(e:DomainEdge):GapEvidenceRef=>({edgeId:e.id,sourceId:e.sourceId,predicate:e.predicate,assertion:e.assertion,model:e.model,design:e.design,limitations:e.limitations,reviewStatus:String((e as unknown as {reviewStatus?:string}).reviewStatus??"unreviewed")});
export const PRIORITY_NOTE="An ordering aid built from the factors listed. It is not a measure of scientific importance and has not been reviewed.";

export function buildGapRegister(bundle:DomainBundle):GapRegisterEntry[]{
 const name=new Map(bundle.nodes.map(n=>[n.id,n.name]));
 const cands=bundle.edges.filter(e=>e.kind==="source_candidate");
 return bundle.gaps.map((g:DomainGap)=>{
  const on=cands.filter(e=>e.subjectId===g.subjectId||e.objectId===g.subjectId||e.subjectId===g.objectId||e.objectId===g.objectId);
  const touching=on.filter(e=>!e.negated).map(ref),opposing=on.filter(e=>e.negated).map(ref);
  const evidenceModels:Partial<Record<DomainModel,number>>={};
  for(const e of on)evidenceModels[e.model]=(evidenceModels[e.model]??0)+1;
  const human=on.filter(e=>HUMAN.has(e.model)).length;
  const direct=on.some(e=>(e.subjectId===g.subjectId&&e.objectId===g.objectId)||(e.subjectId===g.objectId&&e.objectId===g.subjectId));
  const reasons=["No relationship in this graph has been scientifically reviewed."];
  if(!direct)reasons.push("No candidate relationship directly connects the two concepts.");
  if(human===0)reasons.push("No human evidence touches either concept in this graph.");
  if(on.length>0&&on.every(e=>e.contextStatus!=="repository_annotation_not_reverified"))reasons.push("Context for the touching evidence is an editorial annotation pending source verification.");
  const factors=[
   {label:`Spans ${Math.min(g.domains.length,4)} domain${g.domains.length===1?"":"s"}`,points:10*Math.min(g.domains.length,4)},
   {label:`${Math.min(on.length,6)} touching candidate relationship${on.length===1?"":"s"} (capped at 6)`,points:5*Math.min(on.length,6)},
   {label:human===0?"No human evidence recorded":"Human evidence recorded",points:human===0?10:0},
  ];
  return {
   id:g.id,graphVersion:bundle.version,question:g.question,missing:g.missing,
   subject:{id:g.subjectId,name:name.get(g.subjectId)??g.subjectId},object:{id:g.objectId,name:name.get(g.objectId)??g.objectId},
   domains:[...g.domains],conditions:[...g.conditions],touching,opposing,evidenceModels,
   candidateExperiments:[g.nextStudy],
   uncertainty:{level:(direct&&human>0?"moderate":"high") as "high"|"moderate",reasons},
   priority:{score:factors.reduce((s,f)=>s+f.points,0),factors,note:PRIORITY_NOTE},
  };
 }).sort((a,b)=>b.priority.score-a.priority.score||a.id.localeCompare(b.id));
}

/** User-owned tracking, kept separate from the derived entry. */
export type GapEvent={at:string;status:GapStatus;graphVersion:string;touchingCount:number;note?:string};
export type GapTracking=Record<string,{status:GapStatus;history:GapEvent[]}>;
export const MAX_NOTE=300,MAX_HISTORY=50;
/** Generic form: `version` is the graph version or run hash the status was set against; `count` the evidence count then. */
export function recordTracked(t:GapTracking,id:string,version:string,count:number,status:GapStatus,at:string,note?:string):GapTracking{
 if(!GAP_STATUSES.includes(status)||id.length>220)return t;
 const prev=t[id],clean=note?.trim().slice(0,MAX_NOTE)||undefined;
 const ev:GapEvent={at,status,graphVersion:version,touchingCount:count,...(clean?{note:clean}:{})};
 return {...t,[id]:{status,history:[...(prev?.history??[]),ev].slice(-MAX_HISTORY)}};
}
export const recordStatus=(t:GapTracking,entry:GapRegisterEntry,status:GapStatus,at:string,note?:string):GapTracking=>recordTracked(t,entry.id,entry.graphVersion,entry.touching.length+entry.opposing.length,status,at,note);
/** True when the graph now records a different amount of touching evidence than when the researcher last set a status. */
export function evidenceChangedSince(t:GapTracking,entry:GapRegisterEntry):{changed:boolean;from?:number;to:number;sinceVersion?:string}{
 const last=t[entry.id]?.history.at(-1),to=entry.touching.length+entry.opposing.length;
 if(!last)return {changed:false,to};
 return {changed:last.touchingCount!==to,from:last.touchingCount,to,sinceVersion:last.graphVersion};
}
export function parseTracking(raw:string|null):GapTracking{
 if(!raw||raw.length>500_000)return {};
 try{
  const x=JSON.parse(raw);if(!x||typeof x!=="object"||Array.isArray(x))return {};
  const out:GapTracking={};
  for(const [id,v] of Object.entries(x as Record<string,any>)){
   if(id.length>220||!v||!GAP_STATUSES.includes(v.status)||!Array.isArray(v.history))continue;
   const history:GapEvent[]=v.history.filter((h:any)=>h&&GAP_STATUSES.includes(h.status)&&typeof h.at==="string"&&typeof h.graphVersion==="string"&&Number.isInteger(h.touchingCount)).slice(-MAX_HISTORY).map((h:any)=>({at:h.at.slice(0,40),status:h.status,graphVersion:h.graphVersion.slice(0,80),touchingCount:h.touchingCount,...(typeof h.note==="string"&&h.note?{note:h.note.slice(0,MAX_NOTE)}:{})}));
   out[id]={status:v.status,history};
  }
  return out;
 }catch{return {}}
}
